// ── Configs de filtre niveau pour CategoryScreen ────────────────────────────
const CAT_FILTER_CONFIGS = {
  sec: {
    label: "2nde",
    ids: ["numerique","pourcentages","litteral","fonctions","geometrie","statistiques","probabilites","algo_python"],
  },
  // ── 1ère ──
  premiere: {
    label: "1ère",
    ids: ["polynomes","suites","derivation","expo","trigonometrie","produit_scalaire","geometrie","algo_python"],
  },
  premiere_spe: {
    label: "1ère Spé",
    ids: ["polynomes","suites","derivation","expo","trigonometrie","produit_scalaire","geometrie","algo_python"],
  },
  tc: {
    label: "1ère Tronc commun",
    ids: ["numerique","pourcentages","litteral","fonctions","statistiques","probabilites","polynomes","suites","derivation"],
  },
  stmg: {
    label: "1ère STMG",
    ids: ["numerique","pourcentages","litteral","fonctions","statistiques","probabilites","polynomes","suites","derivation"],
  },
  // ── Terminale ──
  term: {
    label: "Terminale",
    ids: ["polynomes","expo","suites","limites","derivation","ln","probabilites","denombrement","trigonometrie","equa_diff","primitives","geometrie","produit_scalaire","algo_python"],
  },
  all: {
    label: "Tout",
    ids: ["numerique","pourcentages","litteral","fonctions","geometrie","statistiques","probabilites","polynomes","expo","suites","derivation","equa_diff","trigonometrie","primitives","limites","denombrement","ln","produit_scalaire","algo_python"],
  },
};

// Convertit le level du profil en clé de filtre
function profileLevelToFilter(level) {
  if (!level) return "all";
  if (level === "sec") return "sec";
  if (level === "tc")   return "tc";
  if (level === "stmg") return "stmg";
  if (level === "spe")  return "premiere_spe";
  if (level === "term") return "term";
  return "all";
}

function CategoryScreen({onCat, onBack, subtitle="", profile=null}) {
  const initFilter = profileLevelToFilter(profile?.level ?? null);
  // Initialiser le sous-filtre 1ère selon le profil
  const initSubFilter = (() => {
    const lv = profile?.level;
    if (lv === "premiere_tronc") return "tc";
    if (lv === "premiere_stmg") return "stmg";
    if (lv === "premiere_spe")  return "premiere_spe";
    return "premiere_spe";
  })();
  const [filter, setFilter] = React.useState(initFilter);
  const [subFilter, setSubFilter] = React.useState(initSubFilter);

  // stmg/tc sont des sous-filtres de "premiere" — afficher onglet 1ère actif
  const displayFilter = (filter === "stmg" || filter === "tc") ? "premiere" : filter;
  const activeFilter = (filter === "premiere" || filter === "stmg" || filter === "tc")
    ? subFilter
    : filter;
  const cfg = CAT_FILTER_CONFIGS[activeFilter] || CAT_FILTER_CONFIGS.all;
  const allCats = CATS.filter(c => c.id !== "missions");
  const visibleCats = cfg.ids.map(id => allCats.find(c => c.id === id)).filter(Boolean);

  const FILTER_TABS = [
    { key:"sec",      label:"2nde" },
    { key:"premiere", label:"1ère" },
    { key:"term",     label:"Terminale" },
    { key:"all",      label:"Tout" },
  ];

  const PREMIERE_SUBTABS = [
    { key:"premiere_spe", label:"Spé" },
    { key:"tc",           label:"Tronc commun" },
    { key:"stmg",         label:"STMG" },
  ];

  return (
    <div className="slide-up" style={{display:"flex",flexDirection:"column",height:"100%",padding:"20px 18px"}}>
      <Back onClick={onBack}/>
      <h2 style={{fontFamily:"'Nunito',sans-serif",fontSize:22,fontWeight:900,color:"#1E293B",marginBottom:4}}>Choisis une catégorie</h2>
      {subtitle && <p style={{color:"#64748B",fontSize:13,marginBottom:8}}>{subtitle}</p>}

      {/* Filtres niveau */}
      <div style={{display:"flex",gap:6,marginBottom: filter==="premiere" ? 8 : 14,flexShrink:0}}>
        {FILTER_TABS.map(tab=>{
          const active = displayFilter === tab.key;
          return (
            <button key={tab.key} onClick={()=>{ setFilter(tab.key); if(tab.key==="premiere") setSubFilter(initSubFilter); }}
              style={{
                flex:1, padding:"6px 4px", borderRadius:10, border:"none",
                background: active ? "#1E293B" : "#F1F5F9",
                color: active ? "#fff" : "#64748B",
                fontFamily:"'Nunito',sans-serif", fontSize:11, fontWeight:800,
                cursor:"pointer", transition:"all .15s",
                boxShadow: active ? "0 2px 8px rgba(30,41,59,.25)" : "none",
              }}>
              {tab.label}
            </button>
          );
        })}
      </div>

      {/* Sous-filtres 1ère */}
      {filter === "premiere" && (
        <div style={{display:"flex",gap:5,marginBottom:14,flexShrink:0}}>
          {PREMIERE_SUBTABS.map(tab=>{
            const active = subFilter === tab.key;
            return (
              <button key={tab.key} onClick={()=>setSubFilter(tab.key)}
                style={{
                  flex:1, padding:"5px 3px", borderRadius:8, border:"none",
                  background: active ? "#7C3AED" : "#F3F0FF",
                  color: active ? "#fff" : "#7C3AED",
                  fontFamily:"'Nunito',sans-serif", fontSize:10, fontWeight:800,
                  cursor:"pointer", transition:"all .15s",
                  boxShadow: active ? "0 2px 6px rgba(124,58,237,.3)" : "none",
                }}>
                {tab.label}
              </button>
            );
          })}
        </div>
      )}

      <Scroll style={{marginTop:0}}>
        {visibleCats.map((c,i)=>(
          <button key={c.id} onClick={()=>onCat(c.id)} className="pop-in"
            style={{background:"#fff",border:`2px solid ${c.border}`,borderRadius:14,padding:"12px 15px",cursor:"pointer",display:"flex",alignItems:"center",gap:12,boxShadow:"0 2px 10px rgba(0,0,0,.06)",animationDelay:`${i*.05}s`,flexShrink:0}}>
            <div style={{width:40,height:40,borderRadius:11,background:c.grad,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>{c.emoji}</div>
            <div style={{textAlign:"left",flex:1}}>
              <div style={{fontFamily:"'Nunito',sans-serif",fontSize:13,fontWeight:800,color:"#1E293B"}}>{c.label}</div>
              <div style={{fontSize:11,color:"#64748B",marginTop:1}}>{c.subs.length} sous-thèmes</div>
            </div>
            <div style={{color:c.color,fontSize:18}}>›</div>
          </button>
        ))}
      </Scroll>
    </div>
  );
}

